foreach ($labels as $tag => [$text, $modifier]) {
    // The English stays as the parameter's DEFAULT, so a template that
    // renders before Localize has run (or on an install without it)
    // reads exactly as it does today rather than going blank.
    $config->rendering->parameters['L_LABEL_'.$tag] = $text;
    $config->BBCodes->addCustom(
        '['.$tag.']',
        '<span class="lmxLabel lmxLabel--'.$modifier.'"><xsl:value-of select="$L_LABEL_'.$tag.'"/></span>'
    );
}

